 "content": "def transform(grid):
    """Project each monochrome 3x3 block's color through its center row/column."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    centers = []
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color == 0:
                continue
            if all(grid[rr][cc] == color
                   for rr in range(r, r + 3)
                   for cc in range(c, c + 3)):
                centers.append((r + 1, c + 1, color))
    # Horizontal rays are drawn first; vertical rays take precedence at crossings.
    for cr, cc, color in centers:
        for c in range(w):
            out[cr][c] = color
    for cr, cc, color in centers:
        for r in range(h):
            out[r][cc] = color
    return out
